definitions.definition:
/// The items below are pub(crate).
/// The hits of one file.
#[derive(Clone, Debug, PartialEq, Eq)]
struct SearchGroup {
    pub path: std::path::PathBuf,
    pub hits: Vec<kate_search::FileHit>,
}

/// The items below are pub(crate).
/// Groups in the order the paths first appear.
fn group_by_file(hits: Vec<kate_search::FileHit>) -> Vec<SearchGroup>
/// `<line + 1>:<col + 1>: <text>`.
fn hit_label(hit: &kate_search::FileHit) -> String
/// A whole-buffer query from the pane toggles. Regex off means Pattern::Plain.
fn pane_query(pattern: &str, regex: bool, case_sensitive: bool, whole_words: bool) -> kate_search::SearchQuery
